most_repeated_storage_engine_query.text:
SET DC_KIND="C32";
SELECT
[Fiscal Year (10)].[Financial Year (248)] AS [Fiscal Year (10)$Financial Year (248)], [Allocation Bridge  derived  (127)].[Fiscal Year Key (611)] AS [Allocation Bridge  derived  (127)$Fiscal Year Key (611)], [Allocation Bridge  derived  (127)].[Rule Key (612)] AS [Allocation Bridge  derived  (127)$Rule Key (612)], [Allocation Bridge  derived  (127)].[Department Key (615)] AS [Allocation Bridge  derived  (127)$Department Key (615)],
SUM([Allocation Bridge  derived  (127)].[Weight  stored  (616)]) AS [$Measure0], MAX([Allocation Bridge  derived  (127)].[Pool Amount  stored  (613)]) AS [$Measure1]
FROM [Allocation Bridge  derived  (127)]
	LEFT OUTER JOIN [Fiscal Year (10)] ON [Allocation Bridge  derived  (127)].[Fiscal Year Key (611)]=[Fiscal Year (10)].[Financial Year (248)];

